/* By hardware supported modes */
#define WDG_66_IA_OFF_MODE          0x1U
#define WDG_66_IA_SLOW_MODE         0x2U
#define WDG_66_IA_FAST_MODE         0x4U

/* These macros are intended to check if watchdog is locked */
#define WDG_66_IA_STATE_UNLOCKED    0x0U
#define WDG_66_IA_STATE_LOCKED      0x1U

/* These macros are intended to check the consistency between configuration setting and related registers */
#define WDG_66_IA_SETTING_NOT_EQUAL 0x0U
#define WDG_66_IA_SETTING_EQUAL     0x1U

/* These macros are intended to check if the enable bit is set */
#define WDG_66_IA_DISABLED_IN_RUN   0x0U
#define WDG_66_IA_ENABLED_IN_RUN    0x1U

/* Defines hardware unit for Wdg module */
#define WDG_HWDG_UNIT               0x0U
#define WDG_SWDG_UNIT_0             0x1U

/* Defines clock type for Wdg module */
#define FastCRClock                 0x0U
#define SlowCRClock                 0x1U
#define SubClock                    0x2U
#define MainClock                   0x3U

/* Defines status type for Wdg module */
#define WDG_66_IA_UNINIT            0x0U
#define WDG_66_IA_IDLE              0x1U
#define WDG_66_IA_BUSY              0x2U

/* Defines trigger mode type for Wdg module */
#define WdgToggle                   0x0U
#define WdgWindow                   0x1U
#define WdgBoth                     0x2U

